# s11_gc2.R -- S11 gate GC2: the values of variant (iii) of S10 (independent script R/s10/testo/s10t_ccvar.R,
# tables/V7_S10_testo_cc_variants.csv) equal those regenerated by the pipeline for the marginalized model with the check:
# Table 5 (tables/V5_S7f_table4.csv, mmm_cc) and Table 3 (tables/variant_cv/V4_S6_values.csv, rate, wc, mad of mmm).
# Preliminary check: variant (i) equals the values before S11 (Table 5 at commit 7a68326; Table 3 from tables/variant_nc).
# Output: tables/V8_S11_gc2.csv
.libPaths("/home/user/MMM/renv/library/linux-ubuntu-noble/R-4.6/x86_64-pc-linux-gnu")
suppressMessages(library(data.table)); setwd("/home/user/MMM")
CV <- fread("tables/V7_S10_testo_cc_variants.csv")
T5 <- fread("tables/V5_S7f_table4.csv")[strategy == "mmm_cc"]; T5o <- fread(cmd = "git show 7a68326:tables/V5_S7f_table4.csv")[strategy == "mmm_cc"]
V3 <- fread("tables/variant_cv/V4_S6_values.csv")[variant == "main"]; V3o <- fread("tables/variant_nc/V4_S6_values.csv")[variant == "main"]
SH <- c(GenBinaryY = "GB", `GLMM-native` = "NAT", `GLMM-AR1` = "AR1"); Q3 <- c(rate_pooled = "rate", worst = "wc", mad_byN = "mad")
R <- list()
for (v in c("iii", "i")) {
  A5 <- if (v == "iii") T5 else T5o; A3 <- if (v == "iii") V3 else V3o
  X <- CV[variant == v & table == "Table 5 (mmm_cc, t, 2376 points)" & quantity != "n_dp"]
  for (j in seq_len(nrow(X))) { q <- X$quantity[j]; a <- as.numeric(X$value[j]); b <- as.numeric(A5[[q]])
    R[[length(R) + 1]] <- data.table(variant = v, table = "Table 5", quantity = q, mechanism = "all", s10 = a, pipeline = b, pass = abs(a - b) < 1e-9) }
  Y <- CV[variant == v & table == "Table 3 (MMM with check, normal, main grid)"]
  for (j in seq_len(nrow(Y))) { nm <- sprintf("%s|%s|mmm", Q3[[Y$quantity[j]]], SH[[Y$mechanism[j]]]); a <- as.numeric(Y$value[j]); b <- A3[name == nm, est]
    R[[length(R) + 1]] <- data.table(variant = v, table = "Table 3", quantity = Y$quantity[j], mechanism = Y$mechanism[j], s10 = a, pipeline = b, pass = length(b) == 1 && abs(a - b) < 1e-9) }
  ch <- CV[variant == v & quantity == "chosen strategy", value]; cp <- (if (v == "iii") fread("tables/V5_S7f_table4.csv") else fread(cmd = "git show 7a68326:tables/V5_S7f_table4.csv"))[chosen == TRUE, strategy]
  R[[length(R) + 1]] <- data.table(variant = v, table = "rule", quantity = "chosen strategy", mechanism = "all", s10 = NA, pipeline = NA, pass = identical(ch, cp))
}
G <- rbindlist(R); fwrite(G, "tables/V8_S11_gc2.csv"); print(G, digits = 10)
cat("GC2:", G[variant == "iii", all(pass)], "| preliminary (variant i = before S11):", G[variant == "i", all(pass)], "\n")
